import { existsSync, readdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const seedPath = join(here, "../../data/pf2e/skill-actions.json");
const generatedDir = join(here, "../../data/pf2e/generated");

/** Unified rule record (generated by `npm run data:pf2e` or from the seed). */
export interface RuleRecord {
  name: string;
  category: string;
  traits?: string[];
  level?: number | null;
  rarity?: string | null;
  text: string;
  source: string;
  /** Foundry actionType: "action" | "reaction" | "free" | "passive" (absent in seed/old data). */
  actionType?: string | null;
  /** Number of actions (1|2|3) when actionType is "action". */
  actionCost?: number | null;
}

interface SeedAction {
  id: string;
  name: string;
  skill: string;
  summary: string;
  criticalSuccess?: string;
  success?: string;
  failure?: string;
  criticalFailure?: string;
}

let index: RuleRecord[] | null = null;
let byName: Map<string, RuleRecord> | null = null;
let sourceLabel = "seed";

function normalize(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .trim();
}

function loadSeed(): RuleRecord[] {
  try {
    const data = JSON.parse(readFileSync(seedPath, "utf8")) as {
      actions: SeedAction[];
    };
    return data.actions.map((a) => ({
      name: a.name,
      category: "actions",
      text: [
        a.summary,
        a.criticalSuccess ? `Critical success: ${a.criticalSuccess}` : "",
        a.success ? `Success: ${a.success}` : "",
        a.failure ? `Failure: ${a.failure}` : "",
        a.criticalFailure ? `Critical failure: ${a.criticalFailure}` : "",
      ]
        .filter(Boolean)
        .join(" "),
      source: "seed",
    }));
  } catch {
    return [];
  }
}

function loadGenerated(): RuleRecord[] {
  const out: RuleRecord[] = [];
  for (const file of readdirSync(generatedDir)) {
    if (!file.endsWith(".json")) continue;
    try {
      const arr = JSON.parse(
        readFileSync(join(generatedDir, file), "utf8"),
      ) as RuleRecord[];
      // Só registros COMPLETOS entram no índice: um .json auxiliar largado na
      // pasta (ex.: feats-classified.json, sem `text`) poluía o lookup com
      // milhares de regras vazias — o modelo consultava e recebia nada.
      out.push(
        ...arr.filter((r) => r && typeof r.name === "string" && r.category && r.text),
      );
    } catch {
      // ignore invalid file
    }
  }
  return out;
}

function load(): RuleRecord[] {
  if (index) return index;
  if (existsSync(generatedDir)) {
    index = loadGenerated();
    sourceLabel = `foundry-generated (${index.length} entries)`;
  }
  if (!index || index.length === 0) {
    index = loadSeed();
    sourceLabel = "seed (run `npm run data:pf2e` for the full dataset)";
  }
  byName = new Map();
  for (const r of index) {
    const key = normalize(r.name);
    // Keep the first (avoids overwriting with same-named variants).
    if (!byName.has(key)) byName.set(key, r);
  }
  return index;
}

/**
 * Looks up a rule by name (any category). Strategy: exact name → substring →
 * highest token overlap. Returns the best match or `null`.
 */
export function lookupLocalRule(query: string): RuleRecord | null {
  const all = load();
  const q = normalize(query);
  if (!q) return null;

  // 1. Exact name.
  const exact = byName!.get(q);
  if (exact) return exact;

  // 2. Substring (prefers the shortest name = most specific match).
  let best: RuleRecord | null = null;
  let bestLen = Infinity;
  for (const r of all) {
    const n = normalize(r.name);
    if (n.includes(q) || q.includes(n)) {
      if (n.length < bestLen) {
        best = r;
        bestLen = n.length;
      }
    }
  }
  if (best) return best;

  // 3. Token overlap.
  const qTokens = new Set(q.split(/\s+/).filter((t) => t.length > 2));
  if (qTokens.size === 0) return null;
  let bestScore = 0;
  for (const r of all) {
    const nTokens = normalize(r.name).split(/\s+/);
    let score = 0;
    for (const t of nTokens) if (qTokens.has(t)) score++;
    if (score > bestScore) {
      bestScore = score;
      best = r;
    }
  }
  return bestScore > 0 ? best : null;
}

export function datasetSource(): string {
  load();
  return sourceLabel;
}

let activityCosts: Map<string, number> | null = null;

/**
 * Detects a MULTI-action activity (feat/action, actionType "action", cost ≥ 2)
 * mentioned inside free text (a roll's reason). Returns its canonical
 * lowercase name and cost, or null. Used by the engine to charge an
 * activity's FULL cost even when the model forgets to pass it — the model
 * naming the activity in `reason` is far more reliable than it passing a
 * separate cost argument. Names < 6 chars are skipped (false-positive prone).
 */
export function multiActionCost(
  text: string,
): { name: string; cost: number } | null {
  if (!activityCosts) {
    activityCosts = new Map();
    for (const r of load()) {
      if (
        (r.category === "feats" || r.category === "actions") &&
        r.actionType === "action" &&
        (r.actionCost ?? 0) >= 2 &&
        r.name.length >= 6
      ) {
        activityCosts.set(r.name.toLowerCase(), r.actionCost!);
      }
    }
  }
  const t = text.toLowerCase();
  for (const [name, cost] of activityCosts) {
    if (t.includes(name)) return { name, cost };
  }
  return null;
}
